(function(root){
'use strict';
const E=root.MigrationEngine||(typeof require!=='undefined'?require('./engine.js'):null);
const KINDS=['Deployment','StatefulSet','DaemonSet','Job','CronJob','Pod'];
const defaults=()=>['Pilot','Application batches','Stateful workloads'].map((name,i)=>({id:'wave-'+(i+1),name,owner:'',entryCriteria:'',exitCriteria:'',rollback:''}));
function object(v,name){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid wave '+name+'.');return v;}
function text(v,name,max=8000){if(typeof v!=='string'||v.length>max)throw Error('Invalid wave '+name+'.');return v.trim();}
function catalog(raw){return E.normalize(raw).items.filter(r=>KINDS.includes(r.kind)&&!(['Pod','Job'].includes(r.kind)&&Array.isArray(r.metadata.ownerReferences)&&r.metadata.ownerReferences.some(o=>o.controller===true))).map(r=>({id:E.id(r),kind:r.kind,namespace:r.metadata.namespace||'default',name:r.metadata.name,stateful:r.kind==='StatefulSet'||!!E.pod(r)?.volumes?.some(v=>v.persistentVolumeClaim||v.hostPath),storageReason:r.kind==='StatefulSet'?'StatefulSet requires a data consistency and recovery review.':E.pod(r)?.volumes?.some(v=>v.persistentVolumeClaim||v.hostPath)?'PVC or hostPath reference requires a data consistency and recovery review.':'No declared PVC/hostPath observed; hidden or external state remains unknown.'}));}
function settings(raw,input={}){object(input,'settings');const workloads=new Set(catalog(raw).map(r=>r.id)),list=input.waves===undefined?defaults():input.waves;if(!Array.isArray(list)||list.length<1||list.length>12)throw Error('Define between 1 and 12 migration waves.');const ids=new Set(),waves=list.map(w=>{object(w,'definition');const id=text(w.id,'id',60);if(!/^wave-[a-z0-9-]+$/.test(id)||ids.has(id))throw Error('Invalid or duplicate wave id.');ids.add(id);const name=text(w.name,'name',120);if(!name)throw Error('Wave name is required.');return {id,name,owner:text(w.owner??'','owner',200),entryCriteria:text(w.entryCriteria??'','entry criteria'),exitCriteria:text(w.exitCriteria??'','exit criteria'),rollback:text(w.rollback??'','rollback criteria')};});const assignments=Object.create(null),records=object(input.assignments??{},'assignments');if(Object.keys(records).length>30000)throw Error('Too many wave assignments.');for(const [id,r] of Object.entries(records)){if(!workloads.has(id))throw Error('Wave assignment refers to an unknown source workload.');object(r,'assignment');const waveId=text(r.waveId??'','selection',60);if(waveId&&!ids.has(waveId))throw Error('Assignment refers to an unknown wave.');const deps=r.dependsOn??[];if(!Array.isArray(deps)||deps.length>20||new Set(deps).size!==deps.length||deps.some(d=>typeof d!=='string'||d===id||!workloads.has(d)))throw Error('Dependencies must be distinct, known source workloads; a workload cannot depend on itself (maximum 20).');assignments[id]={waveId,application:text(r.application??'','application',200),owner:text(r.owner??'','workload owner',200),dependsOn:[...deps],notes:text(r.notes??'','workload notes')};}return {waves,assignments};}
function plan(raw,input={},report={findings:[]}){const config=settings(raw,input),items=catalog(raw),positions=new Map(config.waves.map((w,i)=>[w.id,i])),findings=new Map();for(const f of report.findings||[]){if(!findings.has(f.resource))findings.set(f.resource,[]);findings.get(f.resource).push(f);}const degree=new Map(items.map(x=>[x.id,config.assignments[x.id]?.dependsOn.length||0])),consumers=new Map(items.map(x=>[x.id,[]]));for(const [id,d] of Object.entries(config.assignments))for(const dep of d.dependsOn)consumers.get(dep).push(id);const queue=items.filter(x=>degree.get(x.id)===0).map(x=>x.id);for(let i=0;i<queue.length;i++)for(const child of consumers.get(queue[i])){degree.set(child,degree.get(child)-1);if(degree.get(child)===0)queue.push(child);}const unresolvedCycle=new Set(items.filter(x=>degree.get(x.id)>0).map(x=>x.id));
const rows=items.map(item=>{const d=config.assignments[item.id]||{waveId:'',application:'',owner:'',dependsOn:[],notes:''},gaps=[];if(!d.waveId)gaps.push('No migration wave assigned.');if(!d.application)gaps.push('Application group not recorded.');if(!d.owner)gaps.push('Workload owner not recorded.');const dependencyIssues=d.dependsOn.flatMap(dep=>{const required=config.assignments[dep]?.waveId;if(!required)return [{dependency:dep,type:'Unassigned dependency',detail:'Assign the prerequisite workload to a wave.'}];if(!d.waveId)return [];if(positions.get(required)>positions.get(d.waveId))return [{dependency:dep,type:'Later-wave dependency',detail:'A required workload is planned after its consumer. Reorder waves/assignments or document the retained-source arrangement in notes for owner review; the conflict stays visible.'}];if(required===d.waveId)return [{dependency:dep,type:'Same-wave ordering',detail:'Define manual ordering and readiness checks within this wave.'}];return [];});if(unresolvedCycle.has(item.id))dependencyIssues.push({dependency:item.id,type:'Cycle or dependency on a cycle',detail:'Resolve the dependency chain; no automatic execution order is inferred.'});const open=findings.get(item.id)||[];return {...item,...d,gaps,dependencyIssues,openFindingIds:open.map(f=>f.id),openBlockerIds:open.filter(f=>f.severity==='Blocker').map(f=>f.id)};});
const waves=config.waves.map((w,index)=>{const members=rows.filter(r=>r.waveId===w.id),missing=['owner','entryCriteria','exitCriteria','rollback'].filter(k=>!w[k]);return {...w,order:index+1,workloads:members.map(x=>x.id),missing,planningGaps:missing.length+members.reduce((n,x)=>n+x.gaps.length+x.dependencyIssues.length,0),statefulWorkloads:members.filter(x=>x.stateful).map(x=>x.id),openBlockers:members.reduce((n,x)=>n+x.openBlockerIds.length,0),status:members.length?'Owner review required':'No workloads assigned'};});return {schemaVersion:1,kind:'MigrationWavePlan',gate:'Closed',productionReady:false,workloads:rows,waves,unassigned:rows.filter(r=>!r.waveId).map(r=>r.id),dependencyIssues:rows.flatMap(r=>r.dependencyIssues.map(x=>({workload:r.id,...x}))),cycleAffected:[...unresolvedCycle],note:'Explicit owner-authored grouping and dependencies only. These are planned waves, not an execution schedule or completed gates. Resource-scoped findings remain open; global findings, shared platform resources, external dependencies, data recovery and acceptance require separate review.'};}
function move(config,id,direction){const copy=JSON.parse(JSON.stringify(config)),i=copy.waves.findIndex(w=>w.id===id),to=i+direction;if(![-1,1].includes(direction)||i<0||to<0||to>=copy.waves.length)throw Error('Cannot move this wave in that direction.');[copy.waves[i],copy.waves[to]]=[copy.waves[to],copy.waves[i]];return copy;}
function remove(config,id){if(config.waves.length<=1)throw Error('Keep at least one migration wave.');if(!config.waves.some(w=>w.id===id))throw Error('Unknown migration wave.');if(Object.values(config.assignments).some(a=>a.waveId===id))throw Error('Unassign this wave’s workloads before removing it.');return {...config,waves:config.waves.filter(w=>w.id!==id)};}
function markdown(p){return '# Planned migration waves\n\nProduction gate: CLOSED\n\n'+p.note+'\n\n'+p.waves.map(w=>'## '+w.order+'. '+w.name+'\nOwner: '+(w.owner||'Unassigned')+'\nEntry criteria:\n'+(w.entryCriteria||'Not recorded')+'\nExit criteria:\n'+(w.exitCriteria||'Not recorded')+'\nRollback criteria and procedure:\n'+(w.rollback||'Not recorded')+'\nPlanning gaps: '+w.planningGaps+'\n\n'+p.workloads.filter(r=>r.waveId===w.id).map(r=>'### '+r.id+'\nApplication: '+(r.application||'Unassigned')+'\nOwner: '+(r.owner||'Unassigned')+'\nDepends on: '+(r.dependsOn.join(', ')||'None recorded; completeness unverified')+'\nStorage: '+r.storageReason+'\nOpen resource blocker IDs: '+(r.openBlockerIds.join(', ')||'None detected; global findings remain open')+'\nPlanning gaps: '+(r.gaps.join(' ')||'None recorded')+'\nDependency issues: '+(r.dependencyIssues.map(x=>x.type+': '+x.dependency).join('; ')||'None detected; completeness unverified')+'\nNotes: '+r.notes+'\n').join('\n')).join('\n')+'\n## Unassigned workloads\n'+(p.unassigned.map(id=>'- '+id).join('\n')||'None')+'\n';}
root.MigrationWaves={defaults,catalog,settings,plan,move,remove,markdown};if(typeof module!=='undefined')module.exports=root.MigrationWaves;
})(typeof window!=='undefined'?window:globalThis);
